import{_ as a}from"./chunks/artisan-avatar.Bv6PR6ng.js";import{c as t,Q as s,J as n,h as i,e as o,m as l,l as c,k as d}from"./chunks/framework.WgZQdPFo.js";const v=JSON.parse('{"title":"About the Developers","description":"The story behind OmniCraft ERP, the philosophy of craft, and contacts for the N. Murashkin workshop.","frontmatter":{"title":"About the Developers","description":"The story behind OmniCraft ERP, the philosophy of craft, and contacts for the N. Murashkin workshop.","order":18},"headers":[],"relativePath":"docs/about.md","filePath":"docs/about.md"}'),h={name:"docs/about.md"},u={id:"about-the-developers-from-workbench-to-code",tabindex:"-1"};function p(m,e,f,k,g,b){const r=s("DocIcon");return n(),i("div",null,[o("h1",u,[l(r,{name:"about"}),e[0]||(e[0]=c(" About the Developers: From Workbench to Code ",-1)),e[1]||(e[1]=o("a",{class:"header-anchor",href:"#about-the-developers-from-workbench-to-code","aria-label":'Permalink to "<DocIcon name="about" /> About the Developers: From Workbench to Code"'},"​",-1))]),e[2]||(e[2]=d('<p><strong>OmniCraft ERP</strong> is not the product of a faceless tech corporation or another venture-funded cloud subscription. This platform was born amidst the sawdust and scent of genuine leather, under the rhythmic strike of a mallet and the steady hum of workshop machinery.</p><div class="maker-profile-card"><div class="maker-avatar-wrap"><img src="'+a+'" alt="Nikolay Murashkin — founder of N. Murashkin workshop and creator of OmniCraft ERP" class="maker-avatar-img"><span class="maker-avatar-badge">Maker &amp; Architect</span></div><div class="maker-info"><h3 class="maker-name">Nikolay Murashkin</h3><p class="maker-role">Founder of <strong>N. Murashkin Leather Workshop</strong> and Lead Architect of <strong>OmniCraft ERP</strong></p><p class="maker-quote">&quot;Every line of code in this system has been tested across hundreds of practical hours at the workbench. We built it for ourselves—to lift the exhausting burden of spreadsheet calculations and return what matters most: the pride of honest craft and systematic profit.&quot;</p><div class="maker-links"><a href="https://nmurashkin.ru" target="_blank" rel="noopener noreferrer" class="maker-link-btn"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg> N. Murashkin Workshop (nmurashkin.ru) </a><a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noopener noreferrer" class="maker-link-btn"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 19c-5 1.5-5-2.5-7-3m14 6v-3.87a3.37 3.37 0 0 0-.94-2.61c3.14-.35 6.44-1.54 6.44-7A5.44 5.44 0 0 0 20 4.77 5.07 5.07 0 0 0 19.91 1S18.73.65 16 2.48a13.38 13.38 0 0 0-7 0C6.27.65 5.09 1 5.09 1A5.07 5.07 0 0 0 5 4.77a5.44 5.44 0 0 0-1.5 3.78c0 5.42 3.3 6.61 6.44 7A3.37 3.37 0 0 0 9 18.13V22"></path></svg> Releases Repository </a></div></div></div><hr><h2 id="philosophy-of-craft-and-code" tabindex="-1">Philosophy of Craft and Code <a class="header-anchor" href="#philosophy-of-craft-and-code" aria-label="Permalink to &quot;Philosophy of Craft and Code&quot;">​</a></h2><p>In our workshop, we follow an uncompromising rule: <strong>to build items designed to serve their owners faithfully for decades</strong>. We do not chase disposable consumer trends. Each bag, wallet, and custom piece is engineered for endurance, utilizing first-grade leather and dependable hardware.</p><p>We have carried this exact philosophy of enduring quality into software engineering. OmniCraft ERP was designed as <strong>a lifetime operational asset for the independent artisan</strong>. We believe business software must be:</p><ul><li><strong>Reliable:</strong> Like a lockstitch with waxed thread, the software must never snap when you depend on it. Local database architecture (WAL-journaling, three-tier GFS backups) guarantees data integrity against sudden power failures.</li><li><strong>Autonomous &amp; Sovereign (Local-First):</strong> Your commercial numbers and client rosters belong solely to you. OmniCraft ERP operates locally on your machine, requires no constant cloud connection, and never transmits your financial secrets to external platforms.</li><li><strong>Honest:</strong> We oppose administrative bureaucracy for the sake of ticking boxes. The program communicates in terms of practical value: real cost of goods sold, return on time, and true net margin.</li></ul><hr><h2 id="why-we-created-omnicraft-erp" tabindex="-1">Why We Created OmniCraft ERP <a class="header-anchor" href="#why-we-created-omnicraft-erp" aria-label="Permalink to &quot;Why We Created OmniCraft ERP&quot;">​</a></h2><p>Before building this system, our workshop accounting was fragmented across disjointed spreadsheets, physical logbooks, and smartphone notes. Every time we needed to calculate the real price of a commissioned piece—accounting for leather shipping, tool depreciation, consumable adhesives, and spent working hours—we lost tens of minutes to tedious arithmetic or were forced to quote &quot;by gut feeling.&quot;</p><p>Real workshop experience revealed that creators need an entirely different foundation:</p><ol><li><strong>Automated Precision Over Manual Entry:</strong> The system tracks every square inch of leather, drop of adhesive, and gram of wax automatically using moving average cost (MAC), allocates logistics expenses, and decrements stock upon job delivery.</li><li><strong>Clear Time Valuation:</strong> The master tracks not just top-line revenue, but their actual return per working hour and the workshop&#39;s break-even point.</li><li><strong>Freedom from SaaS Traps:</strong> Zero risk of waking up to locked accounts, sudden 3x price hikes, or revoked access to your own client history.</li></ol><p>Thus OmniCraft ERP was born—a dedicated management suite designed by active makers for makers and small business owners worldwide.</p><hr><h2 id="feedback-and-maker-community" tabindex="-1">Feedback and Maker Community <a class="header-anchor" href="#feedback-and-maker-community" aria-label="Permalink to &quot;Feedback and Maker Community&quot;">​</a></h2><p>We continuously evolve the platform based on our daily workbench practice and ongoing conversations with fellow craftspeople.</p><p>Whether you wish to suggest a specialized module for your trade (such as ceramics, woodworking, or jewelry), report an issue, or exchange ideas—we are always available:</p><ul><li><strong>Official Website:</strong> <a href="https://omnicraft-erp.com" target="_blank" rel="noreferrer">omnicraft-erp.com</a></li><li><strong>Releases Repository:</strong> <a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noreferrer">OmniCraft-ERP-Releases (GitHub)</a></li><li><strong>N. Murashkin Workshop:</strong> <a href="https://nmurashkin.ru" target="_blank" rel="noreferrer">nmurashkin.ru</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Gratitude</p><p>Thank you for choosing OmniCraft ERP. Our purpose is to lift the burden of repetitive calculations and give you back your most precious asset: <strong>time for creative flow, your family, and making items that endure.</strong></p></div>',20))])}const C=t(h,[["render",p]]);export{v as __pageData,C as default};
